{ pkgs, lib, ... }: {
  users.users.alec = { # Default user
    isNormalUser = true;
    extraGroups = [ "wheel" "audio" "video" "dialout" ];
    initialPassword = "nixos";
  };

  boot = {
    loader = {
      systemd-boot = {
        enable = lib.mkDefault true;
        configurationLimit = 2; # Save space in /boot
        editor = false;
      };
      efi.canTouchEfiVariables = true;
      timeout = lib.mkForce 0; # Hold down space on boot to access
    };
    tmp.useTmpfs = true;
    kernelPackages = lib.mkDefault pkgs.linuxPackages_latest;
    kernelParams = [ "nowatchdog" "nmi_watchdog=0" ];
    kernelModules = [ "tcp_bbr" ];
    kernel.sysctl = { # faster network
      "net.ipv4.tcp_congestion_control" = "bbr";
      "net.core.default_qdisc" = "fq"; # pairs with BBR
    };
    initrd.systemd.enable = lib.mkDefault true; # Faster parallel boot
  };

  networking = {
    dhcpcd.enable = false;
    wireless.iwd = {
      enable = lib.mkDefault true;
      settings = {
        IPv6.Enabled = true;
        Settings.AutoConnect = true;
        General.EnableNetworkConfiguration = true;
        Network.NameResolvingService = "systemd";
        Scan.DisablePeriodicScan = true; # not needed
      };
    };
  };

  programs = {
    git = {
      enable = true;
      package = pkgs.gitMinimal;
      config = {
        init.defaultBranch = "main";
        color.ui = true;
        core.editor = "code";
        credential.helper = "store";
        github.user = "AmazinAxel"; # Github
        user.name = "AmazinAxel"; # Git
        push.autoSetupRemote = true;
      };
    };
    command-not-found.enable = false;
  };

  time.timeZone = "America/Los_Angeles"; # lang also set to en_US
  zramSwap.enable = lib.mkDefault true; # Compress ram for better performance

  nixpkgs.config.allowUnfree = true;
  nix.settings = {
    experimental-features = "nix-command flakes";
    auto-optimise-store = true;
    warn-dirty = false;
    trusted-users = [ "alec" ]; # for remote deployments
  };

  services = {
    journald.extraConfig = "SystemMaxUse=20M";
    fstrim.enable = true; # weekly SSD trim
    resolved = {
      enable = true;
      settings.Resolve = {
        MulticastDNS = "no"; # avahi handles mDNS
        DNS = "1.1.1.1#cloudflare-dns.com 1.0.0.1#cloudflare-dns.com";
        #FallbackDNS = "8.8.8.8#dns.google 8.8.4.4#dns.google";
        DNSOverTLS = "opportunistic";
        Domains = "~."; # override DHCP-provided DNS (ISP)
      };
    };
  };
  fileSystems."/".options = [ "noatime" ];
  documentation.enable = false;
  environment.defaultPackages = lib.mkForce [];

  system.stateVersion = lib.mkDefault "24.05";
}
{ inputs, pkgs, ... }: {

  home-manager = {
    extraSpecialArgs = { inherit inputs; };
    users.alec.imports = [ ../home-manager/home.nix ];
    useGlobalPkgs = true; # Faster eval
  };

  environment = {
    systemPackages = with pkgs; [
      # Desktop services
      swaybg
      libnotify # Astal internal notifications
      mpc
      wayfreeze # Screenshot freeze
      grim
      slurp
      swappy # Annotation
      brightnessctl
      adwaita-icon-theme # Icons for GTK apps
      wl-clipboard # Astal clipboard utils
      wl-gammarelay-rs # Blue light filter
      gpu-screen-recorder
      samba # Planning app sync
      cifs-utils # Needed for mounting Samba NAS drive
      rsync # Quickly pull files from NAS drive
      playerctl
      killall
      pass # password management
      gnupg # GPG for passkeys

      # Desktop applications
      gthumb
      gnome-text-editor
      gnome-system-monitor
      nemo-with-extensions
      nemo-fileroller
      file-roller
      discord
      slack
      filezilla
      (prismlauncher.override {
        additionalLibs = [ pkgs.libxkbcommon ]; # TODO remove temp fix
      })
      claude-code

      # vim
      ripgrep # grep
      yazi # search
      viu # neovide images

      # Helix packages
      marksman # markdown
      typescript-language-server # some LSP stuff
      vscode-langservers-extracted # more lSP stuff


      inputs.planning.packages.${pkgs.stdenv.hostPlatform.system}.default

      # Scripts
      (writeScriptBin "fetch" (builtins.readFile ../scripts/fetch.fish))
      (writeScriptBin "sys-sync" (builtins.readFile ../scripts/sys-sync.fish))
      (writeScriptBin "nx-gc" (builtins.readFile ../scripts/nx-gc.fish))
    ];
    sessionVariables = {
      NIXOS_OZONE_WL = "1"; # For Electron
      MOZ_DBUS_REMOTE = "1"; # fix zen screensharing
    };
    etc."samba/smb.conf".text = "[global]"; # Workaround to make samba work without needing to enable the service
  };

  fonts.packages = with pkgs; [
    nerd-fonts.iosevka # Programming
    wqy_zenhei # Chinese
  ];

  programs = {
    dconf.enable = true; # For hm
    nix-ld.enable = true; # For dynamic executables
    gpu-screen-recorder.enable = true; # Clipping & recording software
    gnupg.agent = {
      enable = true;
      pinentryPackage = pkgs.pinentry-gtk2;
    };
  };

  # Chinese input support
  i18n.inputMethod = {
    enable = true;
    type = "fcitx5";
    fcitx5 = {
      addons = with pkgs; [ qt6Packages.fcitx5-chinese-addons fcitx5-nord ];
      waylandFrontend = true;

      settings = {
        inputMethod = {
          "Groups/0" = {
            Name = "Default";
            "Default Layout" = "us";
            DefaultIM = "pinyin";
          };
          "Groups/0/Items/0".Name = "keyboard-us";
          "Groups/0/Items/1".Name = "pinyin";
        };
        globalOptions."Hotkey/TriggerKeys"."0" = "Control+Super+space";

        addons = {
          clipboard.globalSection."TriggerKey" = ""; # Disable clipboard
          classicui.globalSection."Theme" = "Nord-Dark";
