      version = "1.4";
      items = [{
        path      = "${launcherFiles}/share/retroarch/launchers/portmaster.launch";
        label     = "Portmaster";
        core_path = "${launcherCore}/lib/retroarch/cores/launcher_libretro.so";
        core_name = "Launcher";
        crc32     = "00000000|crc";
        db_name   = "portmaster.lpl";
      }];
    };
